const fn = new Function(code + "\nreturn { createModal };");
const { createModal } = fn();
const m = createModal();
if (m.isOpen() !== false) throw new Error("A fresh modal starts closed.");
if (m.open({ id: "trigger" }, {}) !== "opened") throw new Error("open should return opened.");
if (m.isOpen() !== true) throw new Error("After open, isOpen() should be true.");
if (m.close() !== "closed") throw new Error("close should return closed.");
if (m.isOpen() !== false) throw new Error("After close, isOpen() should be false.");

const fn = new Function(code + "\nreturn { createModal };");
const { createModal } = fn();
const m = createModal();
const trigger = { id: "trigger" };
m.open(trigger, {});
m.close();
if (m.restoreFocus() !== trigger) throw new Error("restoreFocus() returns the remembered opener element.");

const fn = new Function(code + "\nreturn { createModal };");
const { createModal } = fn();
const m = createModal();
if (m.open({ id: 1 }, {}) !== "opened") throw new Error("First open succeeds.");
if (m.open({ id: 2 }, {}) !== "already-open") throw new Error("Second open without close returns already-open.");
if (m.close() !== "closed") throw new Error("close still works after the rejected open.");
if (m.close() !== "already-closed") throw new Error("Closing a closed modal returns already-closed.");
if (m.restoreFocus().id !== 1) throw new Error("The rejected open must not overwrite the remembered opener.");
